package alphametics

import (
	"fmt"
	"sort"
	"strings"
	"unicode"
)

// Solve parses an alphametics puzzle of the form
//
//	"TERM1 + TERM2 + ... + TERMN == RESULT"
//
// and returns a mapping from each letter to a distinct digit such that the
// equation holds. Each letter maps to a different digit, and the leading
// letter of a multi-letter word may not map to zero. An error is returned if
// the puzzle is malformed or has no solution.
func Solve(puzzle string) (map[string]int, error) {
	coeff, leading, err := analyze(puzzle)
	if err != nil {
		return nil, err
	}

	letters := make([]string, 0, len(coeff))
	for l := range coeff {
		letters = append(letters, l)
	}
	if len(letters) > 10 {
		return nil, fmt.Errorf("no solution: %d letters cannot map to distinct digits", len(letters))
	}

	// Assign the most influential letters first so the search prunes early.
	sort.Slice(letters, func(i, j int) bool {
		return abs(coeff[letters[i]]) > abs(coeff[letters[j]])
	})

	// maxRem[i] bounds the absolute contribution of letters i..end: each
	// unassigned digit is at most 9.
	maxRem := make([]int, len(letters)+1)
	for i := len(letters) - 1; i >= 0; i-- {
		maxRem[i] = maxRem[i+1] + abs(coeff[letters[i]]) * 9
	}

	assignment := make(map[string]int, len(letters))
	if !search(letters, coeff, leading, assignment, make([]bool, 10), maxRem, 0, 0) {
		return nil, fmt.Errorf("no solution")
	}
	return assignment, nil
}

// analyze parses the puzzle and returns, for each letter, the signed sum of
// the place values it occupies (positive on the left of "==", negative on
// the right), plus the set of letters that may not be zero.
func analyze(puzzle string) (map[string]int, map[string]bool, error) {
	sides := strings.Split(puzzle, "==")
	if len(sides) != 2 {
		return nil, nil, fmt.Errorf("malformed puzzle %q: expected exactly one '=='", puzzle)
	}
	coeff := map[string]int{}
	leading := map[string]bool{}
	add := func(side string, sign int) error {
		for _, term := range strings.Split(side, "+") {
			term = strings.TrimSpace(term)
			if term == "" {
				return fmt.Errorf("malformed puzzle %q: empty term", puzzle)
			}
			for i := 0; i < len(term); i++ {
				if !unicode.IsLetter(rune(term[i])) {
					return fmt.Errorf("malformed puzzle %q: %q is not a word", puzzle, term)
				}
			}
			if len(term) > 1 {
				leading[term[:1]] = true
			}
			place := 1
			for i := len(term) - 1; i >= 0; i-- {
				coeff[term[i:i+1]] += sign * place
				place *= 10
			}
		}
		return nil
	}
	if err := add(strings.TrimSpace(sides[0]), +1); err != nil {
		return nil, nil, err
	}
	if err := add(strings.TrimSpace(sides[1]), -1); err != nil {
		return nil, nil, err
	}
	return coeff, leading, nil
}

// search assigns digits to letters[0..idx) one at a time, keeping the running
// sum of assigned coefficients * digits. It reports whether a complete
// assignment with sum zero exists.
func search(letters []string, coeff map[string]int, leading map[string]bool,
	assignment map[string]int, used []bool, maxRem []int, idx int, sum int) bool {
	if idx == len(letters) {
		return sum == 0
	}
	l := letters[idx]
	min := 0
	if leading[l] {
		min = 1
	}
	for d := min; d < 10; d++ {
		if used[d] {
			continue
		}
		next := sum + coeff[l]*d
		if abs(next) > maxRem[idx+1] {
			continue
		}
		used[d] = true
		assignment[l] = d
		if search(letters, coeff, leading, assignment, used, maxRem, idx+1, next) {
			return true
		}
		delete(assignment, l)
		used[d] = false
	}
	return false
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

